"use client";
import React, { useState, useEffect, useRef } from 'react';
import { Send, Bot, Sparkles, Phone, Calendar, Shield, Activity, Mic, Paperclip, HeartPulse, AlertCircle } from 'lucide-react';

// --- THE CLINIC'S SOURCE OF TRUTH ---
const CLINIC_CONTEXT = {
  name: "Beavers FamilyCare",
  locations: ["Ngong (Main)", "Nairobi", "El Paso"],
  pricing: {
    consultation: "1,500 KES",
    specialist: "3,500 KES",
    lab_fbc: "800 KES",
    maternity_package: "45,000 KES"
  },
  emergency_contact: "+254 700 000 000"
};

export default function BaviUltra() {
  const [messages, setMessages] = useState([
    { role: 'bot', text: "Hello! I'm Bavi 🦫. I've prepared your digital health environment. How can I assist you today?", type: 'text' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState('online');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isTyping]);

  // --- GEMINI API INTEGRATION ---
  const askGemini = async (userPrompt: string) => {
    // Note: In production, call this via a Backend/Serverless Function to hide your API Key
    const GEMINI_API_KEY = "YOUR_GEMINI_API_KEY_HERE"; 
    const API_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`;

    const systemInstruction = `
      You are Bavi, the AI Concierge for ${CLINIC_CONTEXT.name}. 
      Tone: Professional, empathetic, and efficient.
      Context: We are located in ${CLINIC_CONTEXT.locations.join(", ")}. 
      Pricing: Consultation is ${CLINIC_CONTEXT.pricing.consultation}. 
      Rules: 
      1. Always refer to "your health journey."
      2. If an emergency is detected, provide the hotline: ${CLINIC_CONTEXT.emergency_contact}.
      3. Use Markdown for bolding key info.
    `;

    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: `${systemInstruction}\n\nUser: ${userPrompt}` }] }]
        })
      });

      const data = await response.json();
      return data.candidates[0].content.parts[0].text;
    } catch (error) {
      return "I'm having trouble reaching my clinical database. Please call us directly at +254 700 000 000.";
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsTyping(true);

    // Get response from Gemini
    const aiResponse = await askGemini(userMsg);
    
    setMessages(prev => [...prev, { role: 'bot', text: aiResponse }]);
    setIsTyping(false);
    
    // BACKEND SYNC: Here you would also call your database (Supabase/Firebase)
    // await saveChatToDB(userMsg, aiResponse);
  };

  return (
    <div className="flex flex-col h-screen max-w-2xl mx-auto bg-white shadow-2xl border-x border-slate-100 font-sans">
      
      {/* PROFESSIONAL HEADER */}
      <header className="bg-[#0f172a] p-6 text-white flex items-center justify-between shadow-lg">
        <div className="flex items-center gap-4">
          <div className="relative">
            <div className="bg-[#2563eb] p-3 rounded-2xl rotate-3 shadow-blue-500/50 shadow-lg">
              <HeartPulse className="text-white" size={24} />
            </div>
            <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-4 border-[#0f172a] rounded-full"></span>
          </div>
          <div>
            <h1 className="font-black text-2xl tracking-tighter italic">BAVI <span className="text-blue-500">2.0</span> 🦫</h1>
            <p className="text-[10px] text-slate-400 font-bold tracking-[0.3em] uppercase">Powered by Gemini AI</p>
          </div>
        </div>
        <div className="flex gap-4 opacity-70">
          <Phone size={20} className="hover:text-blue-400 cursor-pointer transition-colors" />
          <Calendar size={20} className="hover:text-blue-400 cursor-pointer transition-colors" />
        </div>
      </header>

      {/* CHAT MESSAGES AREA */}
      <main ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`p-4 rounded-3xl text-[15px] leading-relaxed shadow-sm transition-all duration-300 ${
                m.role === 'user' 
                ? 'bg-[#2563eb] text-white rounded-tr-none' 
                : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none font-medium'
              }`}>
                {m.text}
              </div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2">
                {m.role === 'user' ? 'Patient' : 'Bavi Concierge'}
              </span>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex gap-2 items-center text-blue-600 font-bold text-xs animate-pulse">
            <Sparkles size={14} /> Bavi is analyzing...
          </div>
        )}
      </main>

      {/* INTERACTIVE INPUT BAR */}
      <footer className="p-6 bg-white border-t border-slate-100">
        <form onSubmit={handleSend} className="flex flex-col gap-4">
          <div className="flex items-center gap-3 bg-slate-100 p-2 rounded-2xl border border-slate-200 focus-within:border-blue-500 transition-all">
            <button type="button" className="p-2 text-slate-400 hover:text-blue-600"><Paperclip size={20}/></button>
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Describe your symptoms or ask for prices..."
              className="flex-1 bg-transparent py-3 text-slate-700 outline-none font-semibold placeholder:text-slate-400"
            />
            <button type="button" className="p-2 text-slate-400 hover:text-red-500"><Mic size={20}/></button>
            <button 
              type="submit" 
              className="bg-[#0f172a] text-white p-3 rounded-xl hover:bg-blue-600 transition-all shadow-md active:scale-95"
            >
              <Send size={20} />
            </button>
          </div>
          
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
              <Shield size={12} className="text-green-500"/> HIPPA Compliant Encryption
            </div>
            <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
              <AlertCircle size={12} /> Emergency? Dial +254 700 000 000
            </div>
          </div>
        </form>
      </footer>
    </div>
  );
}